new = '''class APIKeyBase(SecurityBase):
    def format_www_authenticate_header_value(self, in_: str, name: str) -> str:
        return f'ApiKey in="{in_}", name="{name}"'

    def check_api_key(self, api_key: Optional[str]) -> Optional[str]:
        if not api_key:
            if self.auto_error:
                status_code = self.not_authenticated_status_code or 401
                headers = {}
                if self.not_authenticated_status_code is None:
                    headers = {"WWW-Authenticate": self.format_www_authenticate_header_value(self.model.in_, self.model.name)}
                raise HTTPException(
                    status_code=status_code, detail="Not authenticated", headers=headers
                )
            return None
        return api_key
'''
